#define _XOPEN_SOURCE 700

#include <errno.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "fileio.h"
#include "platform.h"
#include "uistate.h"
#include "util.h"

/* The words of the file: fixed, independent of the language. */
static const char *const sort_words[UI_SORTS] = {
	"state", "project", "sessions", "size", "modified"
};

void ui_state_default(struct ui_state *st)
{
	st->sort = 1;
	st->reverse = 0;
	st->filter = xstrdup("");
	st->selected = NULL;
	st->split = 500;
}

void ui_state_free(struct ui_state *st)
{
	free(st->filter);
	free(st->selected);
	st->filter = NULL;
	st->selected = NULL;
}

static int same_word(const char *word, const char *text, size_t len)
{
	return strlen(word) == len && memcmp(word, text, len) == 0;
}

static char *copy(const char *text, size_t len)
{
	char *out = xmalloc(len + 1);

	memcpy(out, text, len);
	out[len] = '\0';
	return out;
}

static int blank(int c)
{
	return c == ' ' || c == '\t' || c == '\r';
}

/*
 * Sets value of key; unknown keys and values are left as they are. The
 * filter and the name are taken as they are: blanks may be part of them.
 */
static void ui_state_set(struct ui_state *st, const char *key, size_t klen,
    const char *raw, size_t rlen)
{
	const char *v = raw, *ve = raw + rlen;
	size_t i, n = 0;

	if (same_word("filter", key, klen)) {
		free(st->filter);
		st->filter = copy(raw, rlen);
		return;
	}
	if (same_word("selected", key, klen)) {
		free(st->selected);
		st->selected = rlen > 0 ? copy(raw, rlen) : NULL;
		return;
	}
	while (v < ve && blank(*v))
		v++;
	while (ve > v && blank(ve[-1]))
		ve--;
	if (same_word("sort", key, klen)) {
		for (i = 0; i < UI_SORTS; i++)
			if (same_word(sort_words[i], v, (size_t)(ve - v)))
				st->sort = i;
	} else if (same_word("order", key, klen)) {
		if (same_word("normal", v, (size_t)(ve - v)))
			st->reverse = 0;
		else if (same_word("reverse", v, (size_t)(ve - v)))
			st->reverse = 1;
	} else if (same_word("split", key, klen)) {
		if (v == ve || ve - v > 4)
			return;
		for (; v < ve; v++) {
			if (*v < '0' || *v > '9')
				return;
			n = n * 10 + (size_t)(*v - '0');
		}
		if (n <= 1000)
			st->split = n;
	}
}

/*
 * Lines of "key=value" as in the settings file, "#" starts a comment
 * line. What the file does not say stays as it was.
 */
void ui_state_parse(struct ui_state *st, const char *data, size_t len)
{
	const char *line = data, *end = data + len, *eol, *eq, *k, *ke;

	while (line < end) {
		eol = memchr(line, '\n', (size_t)(end - line));
		if (eol == NULL)
			eol = end;
		eq = memchr(line, '=', (size_t)(eol - line));
		for (k = line; k < eol && blank(*k); k++)
			;
		if (eq != NULL && *k != '#') {
			for (ke = eq; ke > k && blank(ke[-1]); ke--)
				;
			ui_state_set(st, k, (size_t)(ke - k), eq + 1,
			    (size_t)(eol - eq - 1));
		}
		line = eol + 1;
	}
}

/* A text with a line break cannot stand in the file; it is left out. */
char *ui_state_text(const struct ui_state *st)
{
	const char *filter = strchr(st->filter, '\n') == NULL ? st->filter : "";
	const char *selected = st->selected != NULL &&
	    strchr(st->selected, '\n') == NULL ? st->selected : NULL;
	char *text;
	size_t cap;

	cap = strlen(filter) + (selected != NULL ? strlen(selected) : 0) + 96;
	text = xmalloc(cap);
	snprintf(text, cap, "sort=%s\norder=%s\nsplit=%zu\nfilter=%s\n%s%s%s",
	    sort_words[st->sort < UI_SORTS ? st->sort : 1],
	    st->reverse ? "reverse" : "normal", st->split, filter,
	    selected != NULL ? "selected=" : "",
	    selected != NULL ? selected : "", selected != NULL ? "\n" : "");
	return text;
}

/* The file in the state directory; NULL when there is no home for it. */
char *ui_state_path(const char *home)
{
	char *dir, *path;

	dir = platform_state_dir(home);
	if (dir == NULL)
		return NULL;
	path = xjoin(dir, "state");
	free(dir);
	return path;
}

/* Defaults, then the file; a missing file is no error. */
int ui_state_load(const char *path, struct ui_state *st)
{
	char *data;
	size_t len;

	ui_state_default(st);
	if (path == NULL)
		return 0;
	if (file_read(path, &data, &len) != 0)
		return errno == ENOENT ? 0 : -1;
	ui_state_parse(st, data, len);
	free(data);
	return 0;
}
